_saude_config d WHERE id_evento IN ('33486','37483','39399')),'tb_percurso_migracoes_strava',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_percurso_migracoes_strava d WHERE id_evento IN ('33486','37483','39399')),'tb_leaderboard_percurso',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_leaderboard_percurso d WHERE id_evento IN ('33486','37483','39399')),'tb_resultados_resumo',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_resultados_resumo d WHERE id_evento IN ('33486','37483','39399')),'tb_inscricoes',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_inscricoes d WHERE id_evento IN ('33486','37483','39399'))) INTO deps;
IF NOT EXISTS(SELECT 1 FROM tb_evento_corridas z WHERE id_evento=33486 AND md5(to_jsonb(z)::text)='4f80655d1d2129c4bcf85419dea64450') THEN RAISE EXCEPTION 'Baseline drift'; END IF;
